/**
 * Parity of the TS zero-data capacity verification against the conformance
 * primitive vectors (`certcrypt-conformance/fixtures/primitives/`) and against
 * a self-assembled evidence round-trip.
 *
 * The vectors were generated by the reference producer, an independent
 * implementation. If the TS port diverges by one byte on the pseudonym
 * framing or the projected-commitment signing bytes, these tests fail loudly —
 * which is the whole point of the cross-language contract.
 */

import { PROFILE_P256_MLDSA65 } from "../crypto/composite.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import { derivePseudonym, type PseudonymDomain } from "../crypto/pseudonym.js";
import { computeLeafHash, verifyInclusionProof } from "../crypto/merkle.js";
import { projectedCommitmentSigningBytes } from "../types/capacity-evidence.js";
import { verifyCapacityEvidence } from "./capacity-evidence.js";
import { verifyOperationKeyDisclosure } from "../crypto/holder-keyset.js";
import { initMlDsa65 } from "../crypto/ml-dsa.js";

const here = dirname(fileURLToPath(import.meta.url));
// dist/core/independent -> repo root is three up; conformance is a sibling of
// the verifier-toolkit repo.
const PRIMITIVES = join(
  here,
  "..",
  "..",
  "..",
  "..",
  "certcrypt-conformance",
  "fixtures",
  "primitives"
);

function loadVectors(name: string): any | null {
  const p = join(PRIMITIVES, name, "vectors.json");
  if (!existsSync(p)) return null;
  return JSON.parse(readFileSync(p, "utf-8"));
}

test("pseudonym vectors match (framing + KDF parity with the reference producer)", () => {
  const v = loadVectors("pseudonym");
  if (!v) {
    console.error("conformance not found alongside toolkit; skipping");
    return;
  }
  for (const vec of v.vectors) {
    const got = derivePseudonym(
      new TextEncoder().encode(vec.operation_salt_utf8),
      vec.domain as PseudonymDomain,
      vec.stable_id
    );
    assert.equal(
      got,
      vec.expected_pseudonym_hex,
      `pseudonym vector '${vec.name}' diverged — framing or KDF drifted`
    );
  }
  // Load-bearing inequalities.
  const a = derivePseudonym(new TextEncoder().encode("ab"), "holder", "c");
  const b = derivePseudonym(new TextEncoder().encode("a"), "holder", "bc");
  assert.notEqual(a, b, "length-framing must prevent boundary collision");
});

test("holder-keyset vectors match (leaf hash, root, inclusion proofs)", () => {
  const v = loadVectors("holder-keyset");
  if (!v) {
    console.error("conformance not found; skipping");
    return;
  }
  const leafHashes: string[] = [];
  for (const leaf of v.leaves) {
    const pk = new Uint8Array(Buffer.from(leaf.public_key_bytes_hex, "hex"));
    const got = computeLeafHash(pk);
    assert.equal(got, leaf.expected_leaf_hash, `leaf ${leaf.leaf_index} hash drifted`);
    leafHashes.push(got);
  }
  // Inclusion proofs verify against the pinned root.
  const root = v.expected_root;
  for (const proof of v.inclusion_proofs) {
    const idx = proof.leaf_index;
    assert.ok(
      verifyInclusionProof(leafHashes[idx], idx, proof.sibling_hashes, root, leafHashes.length),
      `inclusion proof for leaf ${idx} does not verify against root`
    );
  }
});

test("holder-keyset trees and disclosure cases match (odd widths, fail-closed verdicts)", () => {
  const v = loadVectors("holder-keyset");
  if (!v) {
    console.error("conformance not found; skipping");
    return;
  }
  for (const t of v.trees) {
    const leafHashes = t.public_keys_bytes_hex.map((h: string) =>
      computeLeafHash(new Uint8Array(Buffer.from(h, "hex")))
    );
    for (const p of t.inclusion_proofs) {
      assert.ok(
        verifyInclusionProof(leafHashes[p.leaf_index], p.leaf_index, p.sibling_hashes, t.expected_root, t.tree_size),
        `tree ${t.tree_size}: leaf ${p.leaf_index} does not verify`
      );
    }
    // One past the last index never verifies, even with the last leaf's proof.
    const last = t.inclusion_proofs[t.tree_size - 1];
    assert.equal(
      verifyInclusionProof(leafHashes[t.tree_size - 1], t.tree_size, last.sibling_hashes, t.expected_root, t.tree_size),
      false,
      `tree ${t.tree_size}: index == tree_size must fail`
    );
  }
  assert.ok(v.disclosure_cases.length > 0, "disclosure cases present");
  for (const c of v.disclosure_cases) {
    const got = verifyOperationKeyDisclosure(c.disclosure, c.root);
    assert.equal(got.valid, c.expected_valid, `disclosure case ${c.name}: ${got.reason}`);
  }
});

test("projected-commitment signing bytes match (insertion-order, not JCS)", () => {
  const v = loadVectors("capacity-evidence");
  if (!v) {
    console.error("conformance not found; skipping");
    return;
  }
  const bytes = projectedCommitmentSigningBytes(v.projected_commitment);
  const utf8 = new TextDecoder().decode(bytes);
  assert.equal(
    utf8,
    v.expected_signing_bytes_utf8,
    "projected commitment signing bytes diverged — JCS vs insertion-order, or field order"
  );
  const digest = createHash("sha3-256").update(bytes).digest("hex");
  assert.equal(digest, v.expected_signing_bytes_digest, "signing bytes digest drifted");
  // Guard: NOT JCS (commitment_version must precede authorization_pseudonym).
  assert.ok(
    utf8.indexOf('"commitment_version"') < utf8.indexOf('"authorization_pseudonym"'),
    "signing bytes must be insertion-ordered, not JCS"
  );
});

test("GOLDEN E2E: TS verifier accepts the evidence the reference producer emitted (steps 2-6, offline)", async () => {
  const p = join(PRIMITIVES, "capacity-evidence", "golden-e2e.json");
  if (!existsSync(p)) {
    console.error("golden-e2e.json not found; skipping");
    return;
  }
  // ML-DSA backend is required for the real signature checks (steps 2 & 4).
  const ready = await initMlDsa65();
  assert.ok(ready, "@noble/post-quantum must be installed to run the golden e2e");

  const golden = JSON.parse(readFileSync(p, "utf-8"));

  // Full offline verification of a real (hedged-signed) evidence assembled by
  // the reference producer — no CERTCRYPT contact. This exercises
  // the Level-1 anchor (step 2), membership (3), commitment signature (4),
  // pseudonym bindings (5), and the evidence-digest binding (6). The digest
  // check (6) also proves JSON.stringify(evidence) in TS reproduces the exact
  // bytes the reference producer serialized.
  const verdict = verifyCapacityEvidence(
    golden.evidence,
    golden.system_domain_mldsa_public_key_b64,
    golden.system_domain_p256_public_key_b64,
    golden.expected_evidence_digest,
    PROFILE_P256_MLDSA65
  );
  assert.deepEqual(
    verdict,
    { verified: true },
    `golden evidence must verify offline; got ${JSON.stringify(verdict)}`
  );

  // Negative: wrong system-domain ML-DSA key must fail at step 2 (the anchor).
  // Flip the last base64 char of the real key to get a syntactically valid but
  // wrong key.
  const realKey: string = golden.system_domain_mldsa_public_key_b64;
  const wrongKey =
    realKey.slice(0, -2) + (realKey.slice(-2) === "AA" ? "AB" : "AA");
  const wrongVerdict = verifyCapacityEvidence(
    golden.evidence,
    wrongKey,
    golden.system_domain_p256_public_key_b64,
    golden.expected_evidence_digest,
    PROFILE_P256_MLDSA65
  );
  assert.equal(
    wrongVerdict.verified,
    false,
    "evidence must NOT verify against a wrong system-domain key (step 2 anchor)"
  );

  // Negative: a Level-1 signature declaring another profile fails, even though
  // its components are untouched — the expected profile is the rules domain's.
  const relabelled = JSON.parse(JSON.stringify(golden.evidence));
  relabelled.projected_authorization.level1_signature.alg =
    "certcrypt-composite-ed25519-mldsa65-v1";
  const relabelledVerdict = verifyCapacityEvidence(
    relabelled,
    golden.system_domain_mldsa_public_key_b64,
    golden.system_domain_p256_public_key_b64,
    null,
    PROFILE_P256_MLDSA65
  );
  assert.equal(relabelledVerdict.verified, false, "a non-admitted Level-1 profile must not verify");
  assert.match(
    (relabelledVerdict as { reason?: string }).reason ?? "",
    /profile/,
    "the refusal must name the profile, not a cryptographic failure"
  );

  // Negative: no stable identifier appears in the wire evidence (unlinkability).
  const wire = JSON.stringify(golden.evidence);
  for (const needle of [
    "holder:example",
    "pool:example-default",
    "auth:example-2026",
    "contract:",
  ]) {
    assert.ok(!wire.includes(needle), `stable id '${needle}' leaked into wire evidence`);
  }
});

test("a commitment issued outside its authorization's window is refused (capacity.evidence/1 §8)", async () => {
  const p = join(PRIMITIVES, "capacity-evidence", "golden-e2e.json");
  if (!existsSync(p)) {
    console.error("golden-e2e.json not found; skipping");
    return;
  }
  await initMlDsa65();
  const golden = JSON.parse(readFileSync(p, "utf-8"));
  const issuedAt: string = golden.evidence.projected_commitment.issued_at;

  // Move the window so issued_at falls just before it, then just after it. The
  // window check runs before the Level-1 signature, so the refusal names it.
  const shifted = (from: string, until: string) => {
    const e = structuredClone(golden.evidence);
    e.projected_authorization.valid_from = from;
    e.projected_authorization.valid_until = until;
    e.projected_authorization.level1_binding.valid_from = from;
    e.projected_authorization.level1_binding.valid_until = until;
    return verifyCapacityEvidence(
      e,
      golden.system_domain_mldsa_public_key_b64,
      golden.system_domain_p256_public_key_b64,
      golden.expected_evidence_digest,
      PROFILE_P256_MLDSA65
    );
  };
  const after = new Date(Date.parse(issuedAt) + 1000).toISOString().replace(/\.\d{3}Z$/, "Z");
  const before = new Date(Date.parse(issuedAt) - 1000).toISOString().replace(/\.\d{3}Z$/, "Z");

  for (const verdict of [shifted(after, "2100-01-01T00:00:00Z"), shifted("2000-01-01T00:00:00Z", before)]) {
    assert.equal(verdict.verified, false);
    assert.match(JSON.stringify(verdict), /outside the authorization window/);
  }
});
